INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1011, 'plPL', 'Znalazłem sposób, by dostać się do Komnaty Khaz\'mula!$B$BWeź Medalion Gni\'kiva z mojej skrzyni.$B$BPokonaj trogga Revelosha w komnacie przed pokojem map i zdobądź Drzewce Tsola.$B$BPołącz medalion z drzewcem w Kostur Prehistorii.$B$BUżyj kostura w pokoju map, by otworzyć drzwi do Komnaty Khaz\'mula.$B$BZrób to wszystko, a komnata będzie twoja!$B– Baelog', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(3261, 'plPL', '', 'Nikt nie wykradnie tajemnic Twórców!', 0),
(3400, 'plPL', 'Kto śmie budzić Archaedasa? Kto śmie ściągać na siebie gniew Twórców?', '', 0),
(6212, 'plPL', 'Na brodę Thaurissana! Zabić ich!', '', 0),
(6213, 'plPL', 'Ja Grimlok, król!', '', 0),
(6214, 'plPL', 'Giń! Giń!', '', 0),
(6215, 'plPL', 'Lekkomyślny śmiertelniku!', '', 0),
(6536, 'plPL', 'Przebudźcie się, słudzy! Brońcie Dysków!', '', 0),
(6537, 'plPL', 'Do mnie, bracia! Za Twórców!', '', 0),
(7942, 'plPL', '', 'Witaj, wędrowcze, masz moją dozgonną wdzięczność za pozbycie się tych okropnych stworów! Zdawało mi się już, że przyjdzie mi się tu ukrywać na zawsze!', 0);
